/**
 * Idempotently prepares ios/App/App/Info.plist for BeenBy:
 *
 *  1. Adds the camera/photo usage descriptions (English base text).
 *  2. Declares CFBundleLocalizations for the seven languages BeenBy supports,
 *     so iOS lets the app run in the user's system language instead of
 *     forcing the bundle's single development language.
 *  3. Writes <lang>.lproj/InfoPlist.strings with translated usage strings, so
 *     the permission prompts follow the phone's language.
 *
 * The Info.plist is generated by `npx cap add ios` and is not checked into git,
 * so this script patches whatever exists locally instead of overwriting it.
 *
 * Run: node scripts/patch-ios-plist.mjs
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const APP_DIR = "ios/App/App";
const PLIST = join(APP_DIR, "Info.plist");

const LANGS = ["en", "sv", "de", "da", "fi", "es", "fr"];

/** English base text lives in Info.plist; the rest in InfoPlist.strings. */
const USAGE = {
  en: {
    NSCameraUsageDescription:
      "BeenBy uses the camera when you want to take a photo and share it in the family chat.",
    NSPhotoLibraryUsageDescription:
      "BeenBy needs access to your photos when you want to share a picture in the family chat.",
  },
  sv: {
    NSCameraUsageDescription:
      "BeenBy använder kameran när du vill ta ett foto och dela det i familjechatten.",
    NSPhotoLibraryUsageDescription:
      "BeenBy behöver tillgång till dina bilder när du vill dela ett foto i familjechatten.",
  },
  de: {
    NSCameraUsageDescription:
      "BeenBy nutzt die Kamera, wenn du ein Foto aufnehmen und im Familienchat teilen willst.",
    NSPhotoLibraryUsageDescription:
      "BeenBy braucht Zugriff auf deine Fotos, wenn du ein Bild im Familienchat teilen willst.",
  },
  da: {
    NSCameraUsageDescription:
      "BeenBy bruger kameraet, når du vil tage et billede og dele det i familiechatten.",
    NSPhotoLibraryUsageDescription:
      "BeenBy skal bruge adgang til dine billeder, når du vil dele et billede i familiechatten.",
  },
  fi: {
    NSCameraUsageDescription:
      "BeenBy käyttää kameraa, kun haluat ottaa kuvan ja jakaa sen perhechatissa.",
    NSPhotoLibraryUsageDescription:
      "BeenBy tarvitsee pääsyn kuviisi, kun haluat jakaa kuvan perhechatissa.",
  },
  es: {
    NSCameraUsageDescription:
      "BeenBy usa la cámara cuando quieres hacer una foto y compartirla en el chat familiar.",
    NSPhotoLibraryUsageDescription:
      "BeenBy necesita acceso a tus fotos cuando quieres compartir una imagen en el chat familiar.",
  },
  fr: {
    NSCameraUsageDescription:
      "BeenBy utilise l'appareil photo quand vous voulez prendre une photo et la partager dans le chat familial.",
    NSPhotoLibraryUsageDescription:
      "BeenBy a besoin d'accéder à vos photos quand vous voulez en partager une dans le chat familial.",
  },
};

if (!existsSync(PLIST)) {
  console.error(`Hittar inte ${PLIST}. Kör "npx cap add ios" först.`);
  process.exit(1);
}

let xml = readFileSync(PLIST, "utf8");
const added = [];

// Capacitor's StatusBar plugin must be allowed to control the status bar from
// the bridge view controller. It resizes WKWebView below the status bar when
// overlaysWebView is false.
if (!xml.includes("<key>UIViewControllerBasedStatusBarAppearance</key>")) {
  xml = xml.replace(
    /<dict>/,
    "<dict>\n\t<key>UIViewControllerBasedStatusBarAppearance</key>\n\t<true/>",
  );
  added.push("UIViewControllerBasedStatusBarAppearance");
}

for (const [key, value] of Object.entries(USAGE.en)) {
  if (xml.includes(`<key>${key}</key>`)) continue;
  xml = xml.replace(/<dict>/, `<dict>\n\t<key>${key}</key>\n\t<string>${value}</string>`);
  added.push(key);
}

if (!xml.includes("<key>CFBundleLocalizations</key>")) {
  const list = LANGS.map((l) => `\t\t<string>${l}</string>`).join("\n");
  xml = xml.replace(
    /<dict>/,
    `<dict>\n\t<key>CFBundleLocalizations</key>\n\t<array>\n${list}\n\t</array>`,
  );
  added.push("CFBundleLocalizations");
}

/**
 * Background modes. Without `remote-notification` iOS silently drops the
 * silent/foreground handling of push, and without `location` the geofence
 * plugin stops monitoring when the app is not running.
 */
const BACKGROUND_MODES = ["remote-notification", "location", "fetch"];
if (!xml.includes("<key>UIBackgroundModes</key>")) {
  const list = BACKGROUND_MODES.map((m) => `\t\t<string>${m}</string>`).join("\n");
  xml = xml.replace(
    /<dict>/,
    `<dict>\n\t<key>UIBackgroundModes</key>\n\t<array>\n${list}\n\t</array>`,
  );
  added.push("UIBackgroundModes");
} else {
  for (const mode of BACKGROUND_MODES) {
    if (xml.includes(`<string>${mode}</string>`)) continue;
    xml = xml.replace(
      /<key>UIBackgroundModes<\/key>\s*<array>/,
      (match) => `${match}\n\t\t<string>${mode}</string>`,
    );
    added.push(`UIBackgroundModes:${mode}`);
  }
}

writeFileSync(PLIST, xml);


for (const lang of LANGS) {
  const dir = join(APP_DIR, `${lang}.lproj`);
  mkdirSync(dir, { recursive: true });
  const body = Object.entries(USAGE[lang])
    .map(([key, value]) => `"${key}" = "${value.replace(/"/g, '\\"')}";`)
    .join("\n");
  writeFileSync(join(dir, "InfoPlist.strings"), `${body}\n`, "utf8");
}

console.log(
  `${added.length ? `Lade till: ${added.join(", ")}` : "Info.plist var redan uppdaterad"} · InfoPlist.strings skrevs för: ${LANGS.join(", ")}`,
);
